insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('avocat', 'avocat', array[]::text[], 'list', $r$[{"title":"Poke bowl au saumon","intro":"Du riz vinaigré, du saumon cru mariné au soja, de l'avocat, du concombre et du sésame.","minutes":25,"calories":580,"difficulty":"Facile","imageSearch":"salmon poke bowl","veg":false,"oven":false,"cold":true,"missing":"","origin":"Plat hawaïen","serves":4,"items":[{"name":"riz à sushi","plural":"riz à sushi","qty":250,"unit":"g","have":false},{"name":"pavé de saumon extra-frais","plural":"pavés de saumon extra-frais","qty":2,"unit":"","have":false},{"name":"avocat","plural":"avocats","qty":1,"unit":"","have":false},{"name":"concombre","plural":"concombres","qty":0.5,"unit":"","have":false},{"name":"edamame","plural":"edamame","qty":100,"unit":"g","have":false},{"name":"sauce soja","plural":"sauce soja","qty":3,"unit":"c. à s.","have":false},{"name":"vinaigre de riz","plural":"vinaigre de riz","qty":2,"unit":"c. à s.","have":false},{"name":"graines de sésame","plural":"graines de sésame","qty":1,"unit":"c. à s.","have":false},{"name":"oignon nouveau","plural":"oignons nouveaux","qty":1,"unit":"","have":false}],"steps":[{"text":"Fais cuire le riz, puis mélange-le avec le vinaigre de riz et laisse tiédir.","timer":{"label":"Cuisson","min":15}},{"text":"Coupe le saumon en cubes et fais-le mariner 10 min dans la sauce soja.","timer":{"label":"Marinade","min":10}},{"text":"Coupe l'avocat et le concombre.","timer":null},{"text":"Dans des bols, mets le riz, le saumon, les légumes, les edamame, le sésame et l'oignon.","timer":null}]},{"title":"Poke bowl au poulet","intro":"Le poke bowl en version cuite, au poulet laqué.","minutes":25,"calories":560,"difficulty":"Facile","imageSearch":"chicken poke bowl","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"riz","plural":"riz","qty":250,"unit":"g","have":false},{"name":"blanc de poulet","plural":"blancs de poulet","q