":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":40,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les pâtes.","timer":{"label":"Pâtes","min":10}},{"text":"Fais dorer les champignons émincés dans le beurre avec l'ail 8 min.","timer":{"label":"Poêle","min":8}},{"text":"Ajoute la crème, sale et poivre, et laisse épaissir 2 min.","timer":{"label":"Cuisson","min":2}},{"text":"Mélange avec les pâtes, le persil et le parmesan.","timer":null}],"kids":true},{"title":"Spaghetti carbonara","intro":"La vraie carbonara : des œufs, du pecorino et du guanciale, sans crème.","minutes":20,"calories":650,"difficulty":"Facile","imageSearch":"spaghetti carbonara","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"spaghetti","plural":"spaghetti","qty":400,"unit":"g","have":false},{"name":"guanciale","plural":"guanciale","qty":150,"unit":"g","have":false},{"name":"jaune d'œuf","plural":"jaunes d'œufs","qty":4,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"pecorino râpé","plural":"pecorino râpé","qty":60,"unit":"g","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les spaghetti dans l'eau bouillante salée.","timer":{"label":"Pâtes","min":10}},{"text":"Fais dorer le guanciale en lamelles 5 min à la poêle, sans matière grasse.","timer":{"label":"Poêle","min":5}},{"text":"Bats les jaunes, l'œuf entier, le pecorino et beaucoup de poivre.","timer":null},{"text":"Égoutte les pâtes en gardant un peu d'eau de cuisson, et mets-les dans la poêle hors du feu.","timer":null},{"text":"Verse les œufs en mélangeant vite, avec un peu d'eau de cuisson pour obtenir une sauce crémeuse.","timer":null}]},{"title":"Gnocchis poêlés, sauce tomate et mozzarella","intro":"Des gnocchis dorés à la poêle, dans une sauce tomate avec de la mozzarella fondante.","minutes":20,"calories":520,"difficulty":"Facile","imageSearch":"gnocchi tomato mozzarella","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"gnocchi","plural":"gnocchis","qty":800,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarellas","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":1,"unit":"gousse","have":false},{"name":"basilic","plural":"basilic","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dorer les gnocchis dans l'huile 6 min à la poêle.","timer":{"label":"Poêle","min":6}},{"text":"Ajoute l'ail et les tomates, sale, poivre et cuis 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute la mozzarella en morceaux et le basilic, couvre 2 min pour qu'elle fonde.","timer":{"label":"Cuisson","min":2}}],"kids":true},{"title":"Burger maison","intro":"Un steak juteux, du cheddar fondu, des crudités et une sauce maison dans un pain brioché.","minutes":25,"calories":720,"difficulty":"Facile","imageSearch":"homemade cheeseburger","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat américain","serves":4,"items":[{"name":"pain à burger","plural":"pains à burger","qty":4,"unit":"","have":false},{"name":"steak haché","plural":"steaks hachés","qty":4,"unit":"","have":false},{"name":"cheddar","plural":"cheddar","qty":4,"unit":"tranches","have":false},{"name":"tomate","plural":"tomates","qty":1,"unit":"","have":false},{"name":"oignon rouge","plural":"oignons rouges","qty":1,"unit":"","have":false},{"name":"salade","plural":"salades","qty":4,"unit":"feuilles","have":false},{"name":"cornichon","plural":"cornichons","qty":4,"unit":"","have":false},{"name":"ketchup","plural":"ketchup","qty":2,"unit":"c. à s.","have":false},{"name":"mayonnaise","plural":"mayonnaise","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Mélange le ketchup et la mayonnaise pour la sauce.","timer":null},{"text":"Fais toaster les pains coupés en deux 1 min à la poêle.","timer":{"label":"Poêle","min":1}},{"text":"Fais cuire les steaks 3 min de chaque côté, sale, poivre et pose le cheddar dessus à la fin.","timer":{"label":"Poêle","min":6}},{"text":"Monte les burgers : sauce, salade, steak, tomate, oignon et cornichons.","timer":null}],"kids":true},{"title":"Burritos au bœuf","intro":"De grandes tortillas garnies de bœuf épicé, riz, haricots et fromage.","minutes":35,"calories":680,"difficulty":"Facile","imageSearch":"beef burrito","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat tex-mex","serves":4,"items":[{"name":"bœuf haché","plural":"bœuf haché","qty":400,"unit":"g","have":false},{"name":"riz","plural":"riz","qty":150,"unit":"g","have":false},{"name":"haricot rouge","plural":"haricots rouges","qty":250,"unit":"g","have":false},{"name":"tortilla","plural":"tortillas","qty":4,"unit":"","have":false},{"name":"cheddar râpé","plural":"cheddar râpé","qty":80,"unit":"g","have":false},{"name":"tomate","plural":"tomates","qty":2,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"épices tex-mex","plural":"épices tex-mex","qty":2,"unit":"c. à c.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire le riz.","timer":{"label":"Cuisson","min":12}},{"text":"Fais revenir l'oignon, la viande et les épices 8 min, ajoute les haricots 2 min.","timer":{"label":"Poêle","min":10}},{"text":"Garnis chaque tortilla de riz, de viande, de tomate en dés et de cheddar.","timer":null},{"text":"Replie les côtés puis roule bien serré, et fais dorer 2 min de chaque côté à la poêle.","timer":{"label":"Poêle","min":4}}],"kids":true},{"title":"Boulettes de bœuf à la sauce tomate","intro":"Des boulettes moelleuses, mijotées dans une sauce tomate au basilic.","minutes":40,"calories":520,"difficulty":"Facile","imageSearch":"meatballs tomato sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"bœuf haché","plural":"bœuf haché","qty":500,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"chapelure","plural":"chapelure","qty":40,"unit":"g","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":30,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":800,"unit":"g","have":false},{"name":"basilic","plural":"basilic","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Mélange la viande avec l'œuf, la chapelure, le parmesan, la moitié de l'oignon haché, sel et poivre. Forme des boulettes.","timer":null},{"text":"Fais-les dorer dans l'huile 6 min. Réserve.","timer":{"label":"Poêle","min":6}},{"text":"Fais revenir le reste d'oignon et l'ail, ajoute les tomates et cuis 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Remets les boulettes et laisse mijoter 15 min. Ajoute le basilic.","timer":{"label":"M