.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les œufs 10 min dans l'eau bouillante, puis refroidis-les.","timer":{"label":"Œufs","min":10}},{"text":"Coupe les tomates en quartiers, le poivron en lanières et l'oignon en rondelles fines.","timer":null},{"text":"Dispose les légumes, le thon, les œufs en quartiers, les olives et les anchois.","timer":null},{"text":"Arrose de vinaigrette : huile, vinaigre, sel et poivre.","timer":null}]},{"title":"Lasagnes saumon et épinards","intro":"Des lasagnes crémeuses au saumon et aux épinards.","minutes":70,"calories":600,"difficulty":"Moyen","imageSearch":"salmon spinach lasagna","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"feuille de lasagne","plural":"feuilles de lasagne","qty":12,"unit":"","have":false},{"name":"pavé de saumon","plural":"pavés de saumon","qty":3,"unit":"","have":false},{"name":"épinard","plural":"épinards","qty":400,"unit":"g","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":20,"unit":"cl","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":40,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":60,"unit":"cl","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":50,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais tomber les épinards 5 min à la poêle.","timer":{"label":"Poêle","min":5}},{"text":"Prépare une béchamel, ajoute la crème, sel et poivre.","timer":null},{"text":"Préchauffe le four à 180 °C. Coupe le saumon cru en petits dés.","timer":null},{"text":"Alterne lasagnes, épinards, saumon et béchamel dans un plat, puis parsème de parmesan.","timer":null},{"text":"Enfourne 35 min.","timer":{"label":"Four","min":35}}]},{"title":"Pâtes au saumon fumé","intro":"Encore plus rapide, avec du saumon fumé et de la crème.","minutes":15,"calories":600,"difficulty":"Facile","imageSearch":"smoked salmon pasta","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâtes","plural":"pâtes","qty":400,"unit":"g","have":false},{"name":"saumon fumé","plural":"saumon fumé","qty":200,"unit":"g","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":20,"unit":"cl","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"ciboulette","plural":"ciboulette","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les pâtes.","timer":{"label":"Pâtes","min":10}},{"text":"Fais chauffer la crème avec le zeste de citron et du poivre.","timer":null},{"text":"Mélange les pâtes avec la crème, puis le saumon fumé en lanières et la ciboulette.","timer":null}]},{"title":"Salade de lentilles au saumon fumé","intro":"Une salade de lentilles chic, au saumon fumé.","minutes":35,"calories":420,"difficulty":"Facile","imageSearch":"lentil salad smoked salmon","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"lentille verte","plural":"lentilles vertes","qty":250,"unit":"g","have":false},{"name":"saumon fumé","plural":"saumon fumé","qty":150,"unit":"g","have":false},{"name":"échalote","plural":"échalotes","qty":1,"unit":"","have":false},{"name":"aneth","plural":"aneth","qty":null,"unit":"","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":5,"unit":"cl","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les lentilles 25 min et égoutte-les.","timer":{"label":"Cuisson","min":25}},{"text":"Mélange l'huile, le jus du citron, sel et poivre, et assaisonne les lentilles avec l'échalote.","timer":null},{"text":"Ajoute le saumon en lanières et une cuillère de crème à l'aneth.","timer":null}]},{"title":"Tacos au poisson","intro":"Les tacos de Basse-Californie, au poisson croustillant.","minutes":30,"calories":480,"difficulty":"Facile","imageSearch":"fish tacos","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat mexicain","serves":4,"items":[{"name":"filet de cabillaud","plural":"filets de cabillaud","qty":400,"unit":"g","have":false},{"name":"tortilla de maïs","plural":"tortillas de maïs","qty":12,"unit":"","have":false},{"name":"farine","plural":"farines","qty":3,"unit":"c. à s.","have":false},{"name":"chou blanc","plural":"choux blancs","qty":0.25,"unit":"","have":false},{"name":"mayonnaise","plural":"mayonnaise","qty":3,"unit":"c. à s.","have":false},{"name":"citron vert","plural":"citrons verts","qty":2,"unit":"","have":false},{"name":"coriandre","plural":"coriandre","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe le poisson en bâtonnets, sale et passe-les dans la farine.","timer":null},{"text":"Fais-les dorer dans l'huile 5 min.","timer":{"label":"Poêle","min":5}},{"text":"Mélange la mayonnaise avec le jus d'un citron vert.","timer":null},{"text":"Garnis les tortillas de chou émincé, de poisson, de sauce et de coriandre.","timer":null}]},{"title":"Poisson yassa","intro":"Le yassa au poisson, citronné et fondant.","minutes":50,"calories":420,"difficulty":"Moyen","imageSearch":"fish yassa","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat sénégalais","serves":4,"items":[{"name":"filet de cabillaud","plural":"filets de cabillaud","qty":4,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":5,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":3,"unit":"","have":false},{"name":"moutarde","plural":"moutarde","qty":1,"unit":"c. à s.","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais mariner le poisson 20 min dans le jus des citrons avec l'ail, sel et poivre.","timer":{"label":"Marinade","min":20}},{"text":"Fais fondre les oignons émincés dans l'huile 15 min avec la moutarde.","timer":{"label":"Cuisson","min":15}},{"text":"Pose le poisson sur les oignons, verse la marinade, couvre et cuis 12 min.","timer":{"label":"Cuisson","min":12}}]},{"title":"Choucroute de la mer","intro":"Une choucroute légère au saumon, au cabillaud et aux crevettes.","minutes":60,"calories":480,"difficulty":"Moyen","imageSearch":"fish sauerkraut","veg":false,"oven":false,"cold":false,"missing":"","origin":"Spécialité alsacienne","serves":4,"items":[{"name":"choucroute cuite","plural":"choucroute cuite","qty":1000,"unit":"g","have":false},{"name":"pavé de saumon","plural":"pavés de saumon","qty":2,"unit":"","have":false},{"name":"dos de cabillaud","plural":"dos de cabillaud","qty":2,"unit":"","have":false},{"name":"crevette","plural":"crevettes","qty":8,"unit":"","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":6,"unit":"","have":false},{"name":"vin blanc","plural":"vins blanc","qty":20,"unit":"cl","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":10,"unit":"cl","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais chauffer la choucroute avec le vin blanc 20 min à couvert.","timer":{"label":"Cuisson","min":20}},{"text":"Fais cuire les pommes de terre à la vapeur 25 min.","timer":{"label":"Cuisson","min":25}},{"text":"Pose les poissons et les crevettes sur la choucroute et cuis 10 min à couvert.","timer":{"label":"Cuisson","min":10}},{"text":"Fais chauffer la crème avec le beurre et un peu de jus de cuisson, et nappe le poisson.","timer":null}]},{"title":"Saumon teriyaki","intro":"Un saumon laqué et fondant, à la sauce teriyaki.","minutes":20,"calories":520,"difficulty":"Facile","imageSearch":"salmon teriyaki","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat japonais","serves":4,"items":[{"name":"pavé de saumon","plural":"pavés de saumon","qty":4,"unit":"","have":false},{"name":"sauce soja","plural":"sauce soja","qty":4,"unit":"c. à s.","have":false},{"name":"miel","plural":"miel","qty":2,"unit":"c. à s.","have":false},{"name":"gingembre","plural":"gingembre","qty":1,"unit":"c. à c.","have":false},{"name":"graines de sésame","plural":"graines de sésame","qty":1,"unit":"c. à s.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false}],"steps":[{"text":"Mélange la sauce soja, le miel et le gingembre.","timer":null},{"text":"Fais cuire le saumon côté peau 4 min, retourne-le 2 min.","timer":{"label":"Poêle","min":6}},{"text":"Verse la sauce et laisse réduire 2 min en arrosant le saumon.","timer":{"label":"Poêle","min":2}},{"text":"Parsème de sésame.","timer":null}]},{"title":"Salade niçoise aux pommes de terre et haricots verts","intro":"La niçoise des brasseries, avec pommes de terre et haricots verts.","minutes":35,"calories":520,"difficulty":"Facile","imageSearch":"nicoise salad potatoes green beans","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":4,"unit":"","have":false},{"name":"haricot vert","plural":"haricots verts","qty":200,"unit":"g","have":false},{"name":"tomate","plural":"tomates","qty":3,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"thon au naturel","plural":"thon au naturel","qty":200,"unit":"g","have":false},{"name":"olive noire","plural":"olives noires","qty":60,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":4,"unit":"c. à s.","have":false},{"name":"vinaigre de vin","plural":"vinaigre de vin","qty":1,"unit":"c. à s.","have":false},{"name":"moutarde","plural":"moutarde","qty":1,"unit":"c. à c.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les pommes de terre 20 min et les haricots verts 8 min dans l'eau salée.","timer":{"label":"Cuisson","min":20}},{"text":"Fais cuire les œufs 10 min et écale-les.","timer":{"label":"Œufs","min":10}},{"text":"Prépare la vinaigrette avec la moutarde, le vinaigre, l'huile, sel et poivre.","timer":null},{"text":"Mélange tous les ingrédients coupés et arrose de vinaigrette.","timer":null}]},{"title":"Pâtes au saumon légères","intro":"Une version légère et verte, saumon et épinards.","minutes":20,"calories":480,"difficulty":"Facile","imageSearch":"light salmon spinach pasta","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâtes complètes","plural":"pâtes complètes","qty":350,"unit":"g","have":false},{"name":"pavé de saumon","plural":"pavés de saumon","qty":2,"unit":"","have":false},{"name":"pousse d'épinard","plural":"pousses d'épinard","qty":100,"unit":"g","have":false},{"name":"fromage frais léger","plural":"fromage frais léger","qty":100,"unit":"g","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les pâtes.","timer":{"label":"Pâtes","min":10}},{"text":"Fais cuire le saumon en dés 4 min à la poêle, ajoute les épinards 1 min.","timer":{"label":"Poêle","min":5}},{"text":"Mélange avec les pâtes, le fromage frais, un peu d'eau de cuisson et le jus du citron.","timer":null}]},{"title":"Penne arrabbiata au thon","intro":"L'arrabbiata, avec du thon pour un plat plus complet.","minutes":20,"calories":520,"difficulty":"Facile","imageSearch":"tuna arrabbiata pasta","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"penne","plural":"penne","qty":400,"unit":"g","have":false},{"name":"thon au naturel","plural":"thon au naturel","qty":200,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"piment séché","plural":"piments séchés","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les penne.","timer":{"label":"Pâtes","min":10}},{"text":"Fais revenir l'ail et le piment dans l'huile, ajoute les tomates et cuis 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Ajoute le thon émietté, puis les pâtes.","timer":null}]}]$r$::jsonb, 'claude')
