insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('chevre', 'chèvre', array[]::text[], 'list', $r$[{"title":"Velouté de courgettes au chèvre","intro":"Un velouté de courgettes parfumé au chèvre et au basilic.","minutes":30,"calories":180,"difficulty":"Facile","imageSearch":"zucchini goat cheese soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":4,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"chèvre frais","plural":"chèvres frais","qty":100,"unit":"g","have":false},{"name":"basilic","plural":"basilic","qty":null,"unit":"","have":false},{"name":"bouillon de légumes","plural":"bouillons de légumes","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon dans l'huile 3 min.","timer":{"label":"Cuisson","min":3}},{"text":"Ajoute les courgettes, couvre d'eau avec le bouillon et cuis 20 min.","timer":{"label":"Cuisson","min":20}},{"text":"Mixe avec le chèvre et le basilic, sale et poivre.","timer":null}]},{"title":"Gratin de courgettes au chèvre","intro":"Un gratin parfumé au chèvre fondu et au thym.","minutes":40,"calories":360,"difficulty":"Facile","imageSearch":"zucchini goat cheese gratin","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":4,"unit":"","have":false},{"name":"bûche de chèvre","plural":"bûches de chèvre","qty":1,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":15,"unit":"cl","have":false},{"name":"thym","plural":"thym","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Coupe les courgettes en rondelles et fais-les revenir 8 min dans l'huile.","timer":{"label":"Poêle","min":8}},{"text":"Bats les œufs avec la crème, le thym, sel et poivre.","timer":null},{"text":"Mets les courgettes dans un plat, verse l'appareil et dépose le chèvre en rondelles.","timer":null},{"text":"Enfourne 25 min.","timer":{"label":"Four","min":25}}]},{"title":"Quiche aux poireaux et au chèvre","intro":"Une quiche douce et parfumée, avec des poireaux fondants et du chèvre.","minutes":55,"calories":500,"difficulty":"Facile","imageSearch":"leek goat cheese quiche","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâte brisée","plural":"pâtes brisées","qty":1,"unit":"","have":false},{"name":"poireau","plural":"poireaux","qty":2,"unit":"","have":false},{"name":"bûche de chèvre","plural":"bûches de chèvre","qty":1,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":20,"unit":"cl","have":false},{"name":"lait","plural":"laits","qty":10,"unit":"cl","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Étale la pâte dans un moule.","timer":null},{"text":"Émince les poireaux et fais-les fondre 10 min dans le beurre.","timer":{"label":"Poêle","min":10}},{"text":"Bats les œufs avec la crème, le lait, sel et poivre.","timer":null},{"text":"Répartis les poireaux sur la pâte, verse l'appareil et ajoute le chèvre en rondelles.","timer":null},{"text":"Enfourne 35 min.","timer":{"label":"Four","min":35}}]}]$r$::jsonb, 'claude')
