re","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais chauffer 1 l d'eau avec les bouillons et garde-le frémissant.","timer":null},{"text":"Fais dorer les champignons émincés dans la moitié du beurre 6 min. Réserve.","timer":{"label":"Poêle","min":6}},{"text":"Fais revenir l'échalote dans l'huile, ajoute le riz et nacre-le 2 min, puis verse le vin.","timer":null},{"text":"Ajoute le bouillon louche par louche, en remuant, pendant 18 min.","timer":{"label":"Cuisson","min":18}},{"text":"Hors du feu, ajoute les champignons, le reste du beurre et le parmesan.","timer":null}]},{"title":"Minestrone","intro":"La soupe italienne aux légumes, haricots et petites pâtes, servie avec du parmesan.","minutes":45,"calories":280,"difficulty":"Facile","imageSearch":"minestrone soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"céleri","plural":"céleris","qty":1,"unit":"","have":false},{"name":"haricot blanc","plural":"haricots blancs","qty":250,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"coquillette","plural":"coquillettes","qty":80,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"bouillon de légumes","plural":"bouillons de légumes","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":30,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"po